export type StorageBackend = 'local' | 's3';

/**
 * Identifies the space a set of files belongs to. Every key is built from a
 * scope, so callers can never reach another user's or project's files.
 */
export interface StorageScope {
	projectId: string;
	userId: string;
}

export interface StorageObject {
	key: string;
	size: number;
	contentType?: string;
	lastModified: Date;
}

export interface StorageHealth {
	ok: boolean;
	error?: string;
}

export interface WriteOptions {
	contentType?: string;
}

export interface StorageProvider {
	readonly backend: StorageBackend;
	write(key: string, data: Buffer, options?: WriteOptions): Promise<StorageObject>;
	read(key: string): Promise<Buffer>;
	/** Lists every object below `prefix`, which is matched at path-segment boundaries. */
	list(prefix: string): Promise<StorageObject[]>;
	stat(key: string): Promise<StorageObject | null>;
	exists(key: string): Promise<boolean>;
	delete(key: string): Promise<void>;
	healthCheck(): Promise<StorageHealth>;
}

import type { StorageScope } from './types';

/** S3 caps object keys at 1024 bytes; the same budget keeps local paths sane. */
const MAX_KEY_LENGTH = 1024;

/**
 * Builds the full storage key for a path inside a scope.
 * @throws Error when the scope or path is unsafe.
 */
export const scopedKey = (scope: StorageScope, relativePath: string): string => {
	const key = `${scopeRoot(scope)}/${sanitizeRelativePath(relativePath)}`;

	if (Buffer.byteLength(key) > MAX_KEY_LENGTH) {
		throw new Error(`Path is too long: keys may not exceed ${MAX_KEY_LENGTH} bytes`);
	}

	return key;
};

/** The prefix holding every file for one user in one project. */
export const scopeRoot = (scope: StorageScope): string => {
	return `projects/${safeIdentifier(scope.projectId, 'project id')}/users/${safeIdentifier(scope.userId, 'user id')}`;
};

/** Converts a full storage key back to the path the caller passed in. */
export const relativePathFromKey = (scope: StorageScope, key: string): string => {
	const root = `${scopeRoot(scope)}/`;
	if (!key.startsWith(root)) {
		throw new Error('Key does not belong to this scope');
	}
	return key.slice(root.length);
};

/**
 * Normalises a caller-supplied path into a relative key. Traversal, absolute
 * paths, control characters and Windows separators are rejected rather than
 * silently rewritten, so an unsafe path never resolves to a valid key.
 */
export const sanitizeRelativePath = (relativePath: string): string => {
	if (typeof relativePath !== 'string' || relativePath.trim() === '') {
		throw new Error('Path is required');
	}

	if (relativePath.includes('\0')) {
		throw new Error('Path may not contain null bytes');
	}

	if (relativePath.includes('\\')) {
		throw new Error('Path may not contain backslashes: use / as the separator');
	}

	// eslint-disable-next-line no-control-regex
	if (/[\x00-\x1f\x7f]/.test(relativePath)) {
		throw new Error('Path may not contain control characters');
	}

	const segments = relativePath.split('/').filter((segment) => segment !== '');

	if (segments.length === 0) {
		throw new Error('Path is required');
	}

	for (const segment of segments) {
		if (segment === '.' || segment === '..') {
			throw new Error(`Path may not contain '${segment}' segments`);
		}
		if (segment.trim() === '') {
			throw new Error('Path may not contain blank segments');
		}
	}

	return segments.join('/');
};

const safeIdentifier = (value: string, label: string): string => {
	if (typeof value !== 'string' || value.trim() === '') {
		throw new Error(`Missing ${label}`);
	}
	if (!/^[A-Za-z0-9_-]+$/.test(value)) {
		throw new Error(`Invalid ${label}`);
	}
	return value;
};

import fs from 'node:fs/promises';
import path from 'node:path';

import type { StorageHealth, StorageObject, StorageProvider, WriteOptions } from './types';

const HEALTH_PROBE_KEY = '.nao-storage-health';

/**
 * Stores files on a local directory. When nao runs with more than one replica
 * the root must be a shared read-write-many volume, otherwise each replica
 * sees a different set of files.
 *
 * Content types are not persisted: the filesystem has nowhere to put them.
 */
export class LocalStorageProvider implements StorageProvider {
	readonly backend = 'local' as const;
	readonly root: string;

	constructor(root: string) {
		this.root = path.resolve(root);
	}

	async write(key: string, data: Buffer, options?: WriteOptions): Promise<StorageObject> {
		const filePath = this.toFilePath(key);
		await fs.mkdir(path.dirname(filePath), { recursive: true });
		await fs.writeFile(filePath, data);

		const stats = await fs.stat(filePath);
		return { key, size: stats.size, contentType: options?.contentType, lastModified: stats.mtime };
	}

	async read(key: string): Promise<Buffer> {
		return fs.readFile(this.toFilePath(key));
	}

	async list(prefix: string): Promise<StorageObject[]> {
		const objects: StorageObject[] = [];

		for await (const filePath of this.walk(this.toFilePath(prefix))) {
			const stats = await fs.stat(filePath);
			objects.push({
				key: this.toKey(filePath),
				size: stats.size,
				lastModified: stats.mtime,
			});
		}

		return objects.sort((a, b) => a.key.localeCompare(b.key));
	}

	async stat(key: string): Promise<StorageObject | null> {
		try {
			const stats = await fs.stat(this.toFilePath(key));
			if (!stats.isFile()) {
				return null;
			}
			return { key, size: stats.size, lastModified: stats.mtime };
		} catch (error) {
			if (isNotFound(error)) {
				return null;
			}
			throw error;
		}
	}

	async exists(key: string): Promise<boolean> {
		return (await this.stat(key)) !== null;
	}

	async delete(key: string): Promise<void> {
		await fs.rm(this.toFilePath(key), { force: true });
	}

	async healthCheck(): Promise<StorageHealth> {
		const probePath = path.join(this.root, HEALTH_PROBE_KEY);

		try {
			await fs.mkdir(this.root, { recursive: true });
			await fs.writeFile(probePath, '');
			await fs.rm(probePath, { force: true });
			return { ok: true };
		} catch (error) {
			return { ok: false, error: error instanceof Error ? error.message : String(error) };
		}
	}

	private async *walk(directory: string): AsyncGenerator<string> {
		let entries;
		try {
			entries = await fs.readdir(directory, { withFileTypes: true });
		} catch (error) {
			if (isNotFound(error)) {
				return;
			}
			throw error;
		}

		for (const entry of entries) {
			const entryPath = path.join(directory, entry.name);
			if (entry.isDirectory()) {
				yield* this.walk(entryPath);
			} else if (entry.isFile()) {
				yield entryPath;
			}
		}
	}

	/**
	 * Keys are already sanitised, so this re-check exists to guarantee that no
	 * path can ever resolve outside the root even if a caller bypasses `keys.ts`.
	 */
	private toFilePath(key: string): string {
		const filePath = path.resolve(this.root, key);
		const isInsideRoot = filePath === this.root || filePath.startsWith(this.root + path.sep);

		if (!isInsideRoot) {
			throw new Error(`Access denied: '${key}' resolves outside the storage root`);
		}

		return filePath;
	}

	private toKey(filePath: string): string {
		return path.relative(this.root, filePath).replaceAll(path.sep, '/');
	}
}

const isNotFound = (error: unknown): boolean => {
	return (error as NodeJS.ErrnoException)?.code === 'ENOENT';
};

import {
	DeleteObjectCommand,
	GetObjectCommand,
	HeadBucketCommand,
	HeadObjectCommand,
	ListObjectsV2Command,
	PutObjectCommand,
	S3Client,
} from '@aws-sdk/client-s3';
import { fromNodeProviderChain } from '@aws-sdk/credential-providers';

import type { StorageHealth, StorageObject, StorageProvider, WriteOptions } from './types';

export interface S3StorageConfig {
	bucket: string;
	region?: string;
	endpoint?: string;
	prefix?: string;
	forcePathStyle: boolean;
	accessKeyId?: string;
	secretAccessKey?: string;
}

/**
 * Stores files in an S3 or S3-compatible bucket. Works with AWS S3, MinIO,
 * Cloudflare R2 and Backblaze B2, and needs no privileged container because it
 * talks to the API rather than mounting the bucket.
 */
export class S3StorageProvider implements StorageProvider {
	readonly backend = 's3' as const;

	private readonly client: S3Client;
	private readonly bucket: string;
	private readonly prefix?: string;

	constructor(config: S3StorageConfig) {
		this.bucket = config.bucket;
		this.prefix = config.prefix?.replace(/^\/+|\/+$/g, '') || undefined;
		this.client = new S3Client({
			region: config.region,
			endpoint: config.endpoint,
			forcePathStyle: config.forcePathStyle,
			credentials: buildCredentials(config),
		});
	}

	async write(key: string, data: Buffer, options?: WriteOptions): Promise<StorageObject> {
		await this.client.send(
			new PutObjectCommand({
				Bucket: this.bucket,
				Key: this.toObjectKey(key),
				Body: data,
				ContentType: options?.contentType,
			}),
		);

		return { key, size: data.byteLength, contentType: options?.contentType, lastModified: new Date() };
	}

	async read(key: string): Promise<Buffer> {
		const response = await this.client.send(
			new GetObjectCommand({ Bucket: this.bucket, Key: this.toObjectKey(key) }),
		);

		if (!response.Body) {
			throw new Error(`Object '${key}' has no content`);
		}

		return Buffer.from(await response.Body.transformToByteArray());
	}

	async list(prefix: string): Promise<StorageObject[]> {
		const objects: StorageObject[] = [];
		const listPrefix = this.toObjectKey(prefix.endsWith('/') ? prefix : `${prefix}/`);
		let continuationToken: string | undefined;

		do {
			const response = await this.client.send(
				new ListObjectsV2Command({
					Bucket: this.bucket,
					Prefix: listPrefix,
					ContinuationToken: continuationToken,
				}),
			);

			for (const object of response.Contents ?? []) {
				if (!object.Key) {
					continue;
				}
				objects.push({
					key: this.toStorageKey(object.Key),
					size: object.Size ?? 0,
					lastModified: object.LastModified ?? new Date(0),
				});
			}

			continuationToken = response.IsTruncated ? response.NextContinuationToken : undefined;
		} while (continuationToken);

		return objects.sort((a, b) => a.key.localeCompare(b.key));
	}

	async stat(key: string): Promise<StorageObject | null> {
		try {
			const response = await this.client.send(
				new HeadObjectCommand({ Bucket: this.bucket, Key: this.toObjectKey(key) }),
			);

			return {
				key,
				size: response.ContentLength ?? 0,
				contentType: response.ContentType,
				lastModified: response.LastModified ?? new Date(0),
			};
		} catch (error) {
			if (isNotFound(error)) {
				return null;
			}
			throw error;
		}
	}

	async exists(key: string): Promise<boolean> {
		return (await this.stat(key)) !== null;
	}

	async delete(key: string): Promise<void> {
		await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: this.toObjectKey(key) }));
	}

	async healthCheck(): Promise<StorageHealth> {
		try {
			await this.client.send(new HeadBucketCommand({ Bucket: this.bucket }));
			return { ok: true };
		} catch (error) {
			return { ok: false, error: error instanceof Error ? error.message : String(error) };
		}
	}

	private toObjectKey(key: string): string {
		return this.prefix ? `${this.prefix}/${key}` : key;
	}

	private toStorageKey(objectKey: string): string {
		return this.prefix ? objectKey.slice(this.prefix.length + 1) : objectKey;
	}
}

/**
 * Falls back to the default AWS credential chain so IAM roles, ECS task roles
 * and EKS/IRSA work without any nao-specific configuration.
 */
const buildCredentials = (config: S3StorageConfig) => {
	if (config.accessKeyId && config.secretAccessKey) {
		return { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey };
	}
	return fromNodeProviderChain();
};

const isNotFound = (error: unknown): boolean => {
	const candidate = error as { name?: string; $metadata?: { httpStatusCode?: number } };
	return candidate?.name === 'NotFound' || candidate?.$metadata?.httpStatusCode === 404;
};

import path from 'node:path';

import { env } from '../../env';
import { LocalStorageProvider } from './local.provider';
import { S3StorageProvider } from './s3.provider';
import type { StorageBackend, StorageHealth, StorageProvider } from './types';

export { relativePathFromKey, sanitizeRelativePath, scopedKey, scopeRoot } from './keys';
export type { StorageBackend, StorageHealth, StorageObject, StorageProvider, StorageScope } from './types';

export type CredentialSource = 'explicit' | 'default-chain';

export interface StorageConfigSummary {
	backend: StorageBackend;
	local?: { path: string };
	s3?: {
		bucket: string;
		region?: string;
		endpoint?: string;
		prefix?: string;
		forcePathStyle: boolean;
		credentialSource: CredentialSource;
		accessKeyId?: string;
	};
}

let provider: StorageProvider | null = null;

export const getStorage = (): StorageProvider => {
	provider ??= createProvider();
	return provider;
};

export const getStorageHealth = (): Promise<StorageHealth> => {
	return getStorage().healthCheck();
};

/** Display-safe view of the configuration; secrets never leave this module. */
export const getStorageConfig = (): StorageConfigSummary => {
	if (env.NAO_STORAGE_BACKEND === 's3') {
		return {
			backend: 's3',
			s3: {
				bucket: env.NAO_STORAGE_S3_BUCKET ?? '',
				region: env.NAO_STORAGE_S3_REGION,
				endpoint: env.NAO_STORAGE_S3_ENDPOINT,
				prefix: env.NAO_STORAGE_S3_PREFIX,
				forcePathStyle: env.NAO_STORAGE_S3_FORCE_PATH_STYLE,
				credentialSource: hasExplicitS3Credentials() ? 'explicit' : 'default-chain',
				accessKeyId: maskCredential(env.NAO_STORAGE_S3_ACCESS_KEY_ID),
			},
		};
	}

	return {
		backend: 'local',
		local: { path: path.resolve(env.NAO_STORAGE_LOCAL_PATH) },
	};
};

/** TEST ONLY — drops the cached provider so a new env can take effect. */
export const __resetStorageForTesting = (): void => {
	provider = null;
};

const createProvider = (): StorageProvider => {
	if (env.NAO_STORAGE_BACKEND === 's3') {
		return new S3StorageProvider({
			bucket: env.NAO_STORAGE_S3_BUCKET!,
			region: env.NAO_STORAGE_S3_REGION,
			endpoint: env.NAO_STORAGE_S3_ENDPOINT,
			prefix: env.NAO_STORAGE_S3_PREFIX,
			forcePathStyle: env.NAO_STORAGE_S3_FORCE_PATH_STYLE,
			accessKeyId: env.NAO_STORAGE_S3_ACCESS_KEY_ID,
			secretAccessKey: env.NAO_STORAGE_S3_SECRET_ACCESS_KEY,
		});
	}

	return new LocalStorageProvider(env.NAO_STORAGE_LOCAL_PATH);
};

const hasExplicitS3Credentials = (): boolean => {
	return Boolean(env.NAO_STORAGE_S3_ACCESS_KEY_ID && env.NAO_STORAGE_S3_SECRET_ACCESS_KEY);
};

const maskCredential = (value: string | undefined): string | undefined => {
	if (!value) {
		return undefined;
	}
	if (value.length <= 8) {
		return '••••••••';
	}
	return `${value.slice(0, 4)}••••${value.slice(-4)}`;
};

import { getStorageConfig, getStorageHealth } from '../services/storage';
import { adminProtectedProcedure } from './trpc';

export const storageRoutes = {
	getConfig: adminProtectedProcedure.query(() => getStorageConfig()),

	getHealth: adminProtectedProcedure.query(async () => {
		const health = await getStorageHealth();
		return { ...health, checkedAt: new Date() };
	}),
};

