		await storage.write('projects/p1/users/u1/a.csv', Buffer.from('x'));

		expect(lastInput().Key).toBe('projects/p1/users/u1/a.csv');
		expect(lastInput().Bucket).toBe('my-bucket');
	});

	it('prepends the configured prefix', async () => {
