import path from 'node:path';

import { env } from '../../env';
import { LocalStorageProvider } from './local.provider';
import { S3StorageProvider } from './s3.provider';
import type { StorageBackend, StorageBackendSetting, StorageHealth, StorageProvider } from './types';

export { relativePathFromKey, sanitizeRelativePath, scopedKey, scopeRoot } from './keys';
export {
	isStoragePath,
	STORAGE_SCHEME,
	storageRelativePath,
	toStorageDisplayPath,
	toStorageVirtualPath,
} from './paths';
export type { StorageDirectoryEntry } from './user-files';
export {
	findUserFiles,
	grepRootForUser,
	listUserDirectory,
	readUserFile,
	writeUserFile,
	YOUR_FILES_LABEL,
} from './user-files';
export type {
	StorageBackend,
	StorageBackendSetting,
	StorageHealth,
	StorageObject,
	StorageProvider,
	StorageScope,
} from './types';

export type CredentialSource = 'explicit' | 'default-chain';

export interface StorageConfigSummary {
	backend: StorageBackendSetting;
	local?: { path: string };
	s3?: {
		bucket: string;
		region?: string;
		endpoint?: string;
		prefix?: string;
		forcePathStyle: boolean;
		credentialSource: CredentialSource;
		accessKeyId?: string;
	};
}

export const STORAGE_DISABLED_MESSAGE =
	'Permanent storage is disabled on this nao instance. Ask an admin to set NAO_STORAGE_BACKEND to `local` or `s3`.';

let provider: StorageProvider | null = null;

export const isStorageEnabled = (): boolean => {
	return env.NAO_STORAGE_BACKEND !== 'none';
};

/** @throws Error when permanent storage is disabled. */
export const getStorage = (): StorageProvider => {
	if (!isStorageEnabled()) {
		throw new Error(STORAGE_DISABLED_MESSAGE);
	}
	provider ??= createProvider();
	return provider;
};

export const getStorageHealth = async (): Promise<StorageHealth> => {
	if (!isStorageEnabled()) {
		return { ok: false, error: STORAGE_DISABLED_MESSAGE };
	}
	return getStorage().healthCheck();
};

/** Display-safe view of the configuration; secrets never leave this module. */
export const getStorageConfig = (): StorageConfigSummary => {
	if (env.NAO_STORAGE_BACKEND === 'none') {
		return { backend: 'none' };
	}

	if (env.NAO_STORAGE_BACKEND === 's3') {
		return {
			backend: 's3',
			s3: {
				bucket: env.NAO_STORAGE_S3_BUCKET ?? '',
				region: env.NAO_STORAGE_S3_REGION,
				endpoint: env.NAO_STORAGE_S3_ENDPOINT,
				prefix: env.NAO_STORAGE_S3_PREFIX,
				forcePathStyle: env.NAO_STORAGE_S3_FORCE_PATH_STYLE,
				credentialSource: hasExplicitS3Credentials() ? 'explicit' : 'default-chain',
				accessKeyId: maskCredential(env.NAO_STORAGE_S3_ACCESS_KEY_ID),
			},
		};
	}

	return {
		backend: 'local',
		local: { path: path.resolve(env.NAO_STORAGE_LOCAL_PATH) },
	};
};

/** TEST ONLY — drops the cached provider so a new env can take effect. */
export const __resetStorageForTesting = (): void => {
	provider = null;
};

const createProvider = (): StorageProvider => {
	if (env.NAO_STORAGE_BACKEND === 's3') {
		return new S3StorageProvider({
			bucket: env.NAO_STORAGE_S3_BUCKET!,
			region: env.NAO_STORAGE_S3_REGION,
			endpoint: env.NAO_STORAGE_S3_ENDPOINT,
			prefix: env.NAO_STORAGE_S3_PREFIX,
			forcePathStyle: env.NAO_STORAGE_S3_FORCE_PATH_STYLE,
			accessKeyId: env.NAO_STORAGE_S3_ACCESS_KEY_ID,
			secretAccessKey: env.NAO_STORAGE_S3_SECRET_ACCESS_KEY,
		});
	}

	return new LocalStorageProvider(env.NAO_STORAGE_LOCAL_PATH);
};

const hasExplicitS3Credentials = (): boolean => {
	return Boolean(env.NAO_STORAGE_S3_ACCESS_KEY_ID && env.NAO_STORAGE_S3_SECRET_ACCESS_KEY);
};

const maskCredential = (value: string | undefined): string | undefined => {
	if (!value) {
		return undefined;
	}
	if (value.length <= 8) {
		return '••••••••';
	}
	return `${value.slice(0, 4)}••••${value.slice(-4)}`;
};

/**
 * Permanent storage is addressed by the agent through a scheme, so a path can
 * never be mistaken for a project file: `storage://reports/q3.csv`. The scheme
 * carries no project or user segment — those come from the session.
 */
export const STORAGE_SCHEME = 'storage://';

/** Tolerates the variants a model tends to produce: `storage:/x`, `storage:x`, `STORAGE://x`. */
const SCHEME_PATTERN = /^storage:\/*/i;

export const isStoragePath = (value: string | undefined | null): boolean => {
	return typeof value === 'string' && SCHEME_PATTERN.test(value.trim());
};

/** Path inside the user's space, scheme stripped. An empty string means the root. */
export const storageRelativePath = (value: string): string => {
	return value.trim().replace(SCHEME_PATTERN, '').replace(/^\/+|\/+$/g, '');
};

export const toStorageVirtualPath = (relativePath: string): string => {
	return `${STORAGE_SCHEME}${relativePath}`;
};

import { minimatch } from 'minimatch';

import { getStorage } from '.';
import { relativePathFromKey, sanitizeRelativePath, scopedKey, scopeRoot } from './keys';
import { LocalStorageProvider } from './local.provider';
import type { StorageObject, StorageScope } from './types';

export interface StorageDirectoryEntry {
	name: string;
	/** Path inside the user's space, e.g. `reports/q3.csv`. */
	relativePath: string;
	type: 'file' | 'directory';
	size?: number;
	/** Immediate children, for directories. */
	itemCount?: number;
}

export const readUserFile = async (scope: StorageScope, relativePath: string): Promise<string> => {
	const content = await getStorage().read(scopedKey(scope, relativePath));
	return content.toString('utf-8');
};

export const writeUserFile = async (
	scope: StorageScope,
	relativePath: string,
	content: string,
): Promise<StorageObject> => {
	const key = scopedKey(scope, relativePath);
	return getStorage().write(key, Buffer.from(content, 'utf-8'), { contentType: guessContentType(relativePath) });
};

/**
 * Turns the flat key space into one directory level. Directories only exist as
 * a shared prefix of the keys below them, so an empty one is never listed.
 */
export const listUserDirectory = async (
	scope: StorageScope,
	relativeDir: string,
): Promise<StorageDirectoryEntry[]> => {
	const base = relativeDir === '' ? '' : `${sanitizeRelativePath(relativeDir)}/`;
	const objects = await getStorage().list(relativeDir === '' ? scopeRoot(scope) : scopedKey(scope, relativeDir));

	const files: StorageDirectoryEntry[] = [];
	const directoryChildren = new Map<string, Set<string>>();

	for (const object of objects) {
		const relativePath = relativePathFromKey(scope, object.key);
		if (!relativePath.startsWith(base)) {
			continue;
		}

		const [name, ...rest] = relativePath.slice(base.length).split('/');
		if (!name) {
			continue;
		}

		if (rest.length === 0) {
			files.push({ name, relativePath, type: 'file', size: object.size });
			continue;
		}

		const children = directoryChildren.get(name) ?? new Set<string>();
		children.add(rest[0]!);
		directoryChildren.set(name, children);
	}

	const directories = [...directoryChildren].map(([name, children]) => ({
		name,
		relativePath: `${base}${name}`,
		type: 'directory' as const,
		itemCount: children.size,
	}));

	return [...sortByName(directories), ...sortByName(files)];
};

export const findUserFiles = async (scope: StorageScope, pattern: string): Promise<StorageObject[]> => {
	const objects = await getStorage().list(scopeRoot(scope));
	const recursivePattern = pattern.startsWith('**/') ? pattern : `**/${pattern}`;

	return objects.filter((object) =>
		minimatch(relativePathFromKey(scope, object.key), recursivePattern, { dot: true }),
	);
};

/**
 * Absolute directory holding the user's files, for tools that need a real
 * filesystem (content search).
 * @throws Error when the backend is not `local`.
 */
export const grepRootForUser = (scope: StorageScope): string => {
	const storage = getStorage();

	if (!(storage instanceof LocalStorageProvider)) {
		throw new Error(
			'Searching file contents in permanent storage requires the `local` storage backend. On the `s3` backend, use search to find files by name and read them instead.',
		);
	}

	return storage.toFilePath(scopeRoot(scope));
};

const CONTENT_TYPES: Record<string, string> = {
	csv: 'text/csv',
	html: 'text/html',
	json: 'application/json',
	md: 'text/markdown',
	sql: 'application/sql',
	tsv: 'text/tab-separated-values',
	txt: 'text/plain',
	xml: 'application/xml',
	yaml: 'application/yaml',
	yml: 'application/yaml',
};

const guessContentType = (relativePath: string): string => {
	const extension = relativePath.split('.').pop()?.toLowerCase() ?? '';
	return CONTENT_TYPES[extension] ?? 'text/plain';
};

const sortByName = <T extends { name: string }>(entries: T[]): T[] => {
	return [...entries].sort((a, b) => a.name.localeCompare(b.name));
};

