import { list } from '@nao/shared/tools';
import fs from 'fs/promises';
import path from 'path';

import { ListOutput, renderToModelOutput } from '../../components/tool-outputs';
import { isStorageEnabled } from '../../services/storage';
import { listUserDirectory } from '../../services/storage/user-files';
import type { ToolContext } from '../../types/tools';
import {
	isStoragePath,
	shouldExcludeEntry,
	STORAGE_MOUNT,
	toRealPath,
	toStorageRelativePath,
	toStorageScope,
	toStorageVirtualPath,
	toVirtualPath,
} from '../../utils/tools';
import { createTool } from '../../utils/tools';

export default createTool<list.Input, list.Output>({
	description: 'List files and directories at the specified path.',
	inputSchema: list.InputSchema,
	outputSchema: list.OutputSchema,
	execute: async ({ path: filePath }, context) => {
		const entries = isStoragePath(filePath)
			? await listStorage(filePath, context)
			: await listProjectFolder(filePath, context);

		return { _version: '1' as const, entries };
	},

	toModelOutput: ({ output }) => renderToModelOutput(ListOutput({ output }), output),
});

const listStorage = async (virtualPath: string, context: ToolContext): Promise<list.Entry[]> => {
	const entries = await listUserDirectory(toStorageScope(context), toStorageRelativePath(virtualPath));

	return entries.map((entry) => ({
		path: toStorageVirtualPath(entry.relativePath),
		name: entry.name,
		type: entry.type,
		size: entry.size?.toString(),
		itemCount: entry.itemCount,
	}));
};

const listProjectFolder = async (virtualPath: string, context: ToolContext): Promise<list.Entry[]> => {
	const projectFolder = context.projectFolder;
	const realPath = toRealPath(virtualPath, projectFolder);

	// Get the relative path of the parent directory for naoignore matching
	const parentRelativePath = path.relative(projectFolder, realPath);

	const dirEntries = await fs.readdir(realPath, { withFileTypes: true });

	// Filter out excluded entries (including .naoignore patterns)
	const filteredEntries = dirEntries.filter(
		(entry) => !shouldExcludeEntry(entry.name, parentRelativePath, projectFolder),
	);

	const entries = await Promise.all(
		filteredEntries.map(async (entry) => {
			const fullRealPath = path.join(realPath, entry.name);

			const type: 'file' | 'directory' | 'symbolic_link' | undefined = entry.isDirectory()
				? 'directory'
				: entry.isFile()
					? 'file'
					: entry.isSymbolicLink()
						? 'symbolic_link'
						: undefined;
			const size = type === 'directory' ? undefined : (await fs.stat(fullRealPath)).size.toString();

			let itemCount: number | undefined;
			if (type === 'directory') {
				try {
					const subEntries = await fs.readdir(fullRealPath);
					itemCount = subEntries.length;
				} catch {
					// If we can't read the directory, leave itemCount undefined
				}
			}

			return {
				path: toVirtualPath(fullRealPath, projectFolder),
				name: entry.name,
				type,
				size,
				itemCount,
			};
		}),
	);

	const isRoot = parentRelativePath === '';
	return isRoot && isStorageEnabled() ? [...entries, await storageMountEntry(context)] : entries;
};

/** Permanent storage shows up as an ordinary folder at the root of the tree. */
const storageMountEntry = async (context: ToolContext): Promise<list.Entry> => {
	const entry = {
		path: toStorageVirtualPath(''),
		name: STORAGE_MOUNT,
		type: 'directory' as const,
	};

	try {
		const files = await listUserDirectory(toStorageScope(context), '');
		return { ...entry, itemCount: files.length };
	} catch {
		// An unreachable storage backend must not break listing the project
		return entry;
	}
};

import { searchFiles } from '@nao/shared/tools';
import fs from 'fs/promises';
import { glob } from 'glob';
import { minimatch } from 'minimatch';
import path from 'path';

import { renderToModelOutput, SearchOutput } from '../../components/tool-outputs';
import { isStorageEnabled, relativePathFromKey } from '../../services/storage';
import { findUserFiles } from '../../services/storage/user-files';
import type { ToolContext } from '../../types/tools';
import {
	isWithinProjectFolder,
	loadNaoignorePatterns,
	STORAGE_MOUNT,
	toStorageScope,
	toStorageVirtualPath,
	toVirtualPath,
} from '../../utils/tools';
import { createTool } from '../../utils/tools';

export default createTool<searchFiles.Input, searchFiles.Output>({
	description: 'Search for files matching a glob pattern within the project.',
	inputSchema: searchFiles.InputSchema,
	outputSchema: searchFiles.OutputSchema,
	execute: async ({ pattern }, context) => {
		// Sanitize pattern to prevent escaping the tree
		if (path.isAbsolute(pattern)) {
			throw new Error(`Access denied: absolute paths are not allowed in file patterns`);
		}
		if (pattern.includes('..')) {
			throw new Error(`Access denied: '..' is not allowed in file patterns`);
		}

		// Make pattern recursive if not already
		const recursivePattern = pattern.startsWith('**/') ? pattern : `**/${pattern}`;

		const [projectFiles, storageFiles] = await Promise.all([
			searchProjectFolder(recursivePattern, context.projectFolder),
			searchStorage(recursivePattern, context),
		]);

		return { _version: '1' as const, files: [...projectFiles, ...storageFiles] };
	},

	toModelOutput: ({ output }) => renderToModelOutput(SearchOutput({ output }), output),
});

const searchStorage = async (recursivePattern: string, context: ToolContext): Promise<searchFiles.File[]> => {
	if (!isStorageEnabled()) {
		return [];
	}

	const scope = toStorageScope(context);
	const objects = await findUserFiles(scope, (relativePath) =>
		minimatch(`${STORAGE_MOUNT}/${relativePath}`, recursivePattern, { dot: true }),
	);

	return objects.map((object) => {
		const virtualPath = toStorageVirtualPath(relativePathFromKey(scope, object.key));
		return {
			path: virtualPath,
			dir: path.dirname(virtualPath),
			size: object.size.toString(),
		};
	});
};

const searchProjectFolder = async (recursivePattern: string, projectFolder: string): Promise<searchFiles.File[]> => {
	// Build ignore patterns from .naoignore
	const naoignorePatterns = loadNaoignorePatterns(projectFolder);
	const ignorePatterns = naoignorePatterns.flatMap((ignorePattern) => {
		const cleanPattern = ignorePattern.endsWith('/') ? ignorePattern.slice(0, -1) : ignorePattern;
		return [`**/${cleanPattern}`, `**/${cleanPattern}/**`];
	});

	const matchedPaths = await glob(recursivePattern, {
		absolute: true,
		cwd: projectFolder,
		ignore: ignorePatterns,
	});

	// Filter to only files within the project folder and not in excluded dirs (double-check)
	const safeFiles = matchedPaths.filter((f) => isWithinProjectFolder(f, projectFolder));

	return Promise.all(
		safeFiles.map(async (realPath) => {
			const stats = await fs.stat(realPath);
			const virtualPath = toVirtualPath(realPath, projectFolder);

			return {
				path: virtualPath,
				dir: path.dirname(virtualPath),
				size: stats.size.toString(),
			};
		}),
	);
};

import { grep } from '@nao/shared/tools';
import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';

import { GrepOutput, renderToModelOutput } from '../../components/tool-outputs';
import { isStorageEnabled } from '../../services/storage';
import { canGrepUserFiles, grepRootForUser } from '../../services/storage/user-files';
import type { ToolContext } from '../../types/tools';
import {
	isStoragePath,
	isWithinProjectFolder,
	loadNaoignorePatterns,
	toRealPath,
	toStorageRelativePath,
	toStorageScope,
	toStorageVirtualPath,
	toVirtualPath,
} from '../../utils/tools';
import { createTool } from '../../utils/tools';

/**
 * Gets the path to the ripgrep binary.
 * Priority:
 * 1. Bundled binary next to the executable (for standalone builds)
 * 2. vscode-ripgrep package (for development)
 */
function getRipgrepPath(): string {
	// Check for bundled binary next to the executable
	const execDir = path.dirname(process.execPath);
	const bundledRgPath = path.join(execDir, process.platform === 'win32' ? 'rg.exe' : 'rg');

	if (fs.existsSync(bundledRgPath)) {
		return bundledRgPath;
	}

	// Fall back to vscode-ripgrep package
	try {
		// Dynamic import to avoid bundling issues
		// eslint-disable-next-line @typescript-eslint/no-require-imports
		const { rgPath } = require('@vscode/ripgrep');
		if (fs.existsSync(rgPath)) {
			return rgPath;
		}
	} catch {
		// Package not available
	}

	throw new Error(
		'ripgrep binary not found. Ensure @vscode/ripgrep is installed or the binary is bundled with the executable.',
	);
}

interface RipgrepMatch {
	path: string;
	line_number: number;
	line_content: string;
	context_before?: string[];
	context_after?: string[];
}

/** A directory ripgrep walks, and how its absolute paths map back to the file tree. */
interface SearchTarget {
	root: string;
	cwd: string;
	ignoreGlobs: string[];
	/** Returns null when a match must be dropped because it sits outside the target. */
	toDisplayPath: (absolutePath: string) => string | null;
	toAbsolutePath: (displayPath: string) => string;
}

interface TargetResult {
	matches: RipgrepMatch[];
	totalMatches: number;
}

export default createTool<grep.Input, grep.Output>({
	description: 'Search for text patterns in files using ripgrep. Supports regex patterns and respects .gitignore.',
	inputSchema: grep.InputSchema,
	outputSchema: grep.OutputSchema,
	execute: async ({ max_results = 100, ...options }, context) => {
		const rgPath = getRipgrepPath();
		const targets = resolveTargets(options.path, context);

		const results = await Promise.all(
			targets.map((target) => searchTarget(rgPath, target, { ...options, max_results })),
		);

		const totalMatches = results.reduce((total, result) => total + result.totalMatches, 0);
		const matches = results.flatMap((result) => result.matches).slice(0, max_results);

		return {
			_version: '1',
			matches,
			total_matches: totalMatches,
			truncated: totalMatches > matches.length,
		};
	},

	toModelOutput: ({ output }) => renderToModelOutput(GrepOutput({ output }), output),
});

/** A search without a path covers the whole tree, permanent storage included. */
const resolveTargets = (searchPath: string | undefined, context: ToolContext): SearchTarget[] => {
	if (isStoragePath(searchPath)) {
		return [storageTarget(searchPath!, context)];
	}
	if (searchPath) {
		return [projectTarget(searchPath, context.projectFolder)];
	}

	const storage = isStorageEnabled() && canGrepUserFiles() ? [storageTarget(toStorageVirtualPath(''), context)] : [];
	return [projectTarget(undefined, context.projectFolder), ...storage];
};

const projectTarget = (searchPath: string | undefined, projectFolder: string): SearchTarget => {
	return {
		root: searchPath ? toRealPath(searchPath, projectFolder) : projectFolder,
		cwd: projectFolder,
		ignoreGlobs: loadNaoignorePatterns(projectFolder),
		toDisplayPath: (absolutePath) =>
			isWithinProjectFolder(absolutePath, projectFolder) ? toVirtualPath(absolutePath, projectFolder) : null,
		toAbsolutePath: (displayPath) => toRealPath(displayPath, projectFolder),
	};
};

const storageTarget = (searchPath: string, context: ToolContext): SearchTarget => {
	const scope = toStorageScope(context);
	const spaceRoot = grepRootForUser(scope);

	return {
		root: grepRootForUser(scope, toStorageRelativePath(searchPath)),
		cwd: spaceRoot,
		ignoreGlobs: [],
		toDisplayPath: (absolutePath) => {
			const relativePath = path.relative(spaceRoot, path.resolve(absolutePath));
			if (relativePath === '' || relativePath.startsWith('..')) {
				return null;
			}
			return toStorageVirtualPath(relativePath.replaceAll(path.sep, '/'));
		},
		toAbsolutePath: (displayPath) => grepRootForUser(scope, toStorageRelativePath(displayPath)),
	};
};

function searchTarget(
	rgPath: string,
	target: SearchTarget,
	{ pattern, glob, case_insensitive, context_lines, max_results }: grep.Input & { max_results: number },
): Promise<TargetResult> {
	if (!fs.existsSync(target.root)) {
		return Promise.resolve({ matches: [], totalMatches: 0 });
	}

	// Build ripgrep arguments
	const args: string[] = [
		'--json', // JSON output for structured parsing
		'--no-heading',
		'--line-number',
	];

	if (case_insensitive) {
		args.push('--ignore-case');
	}

	if (context_lines && context_lines > 0) {
		args.push('--context', context_lines.toString());
	}

	if (glob) {
		args.push('--glob', glob);
	}

	for (const ignorePattern of target.ignoreGlobs) {
		// Convert naoignore patterns to ripgrep glob exclusions
		const cleanPattern = ignorePattern.endsWith('/') ? ignorePattern.slice(0, -1) : ignorePattern;
		args.push('--glob', `!${cleanPattern}`);
		args.push('--glob', `!${cleanPattern}/**`);
	}

	// Add the pattern and path
	args.push('--regexp', pattern);
	args.push('--', target.root);

	return new Promise((resolve, reject) => {
		const matches: RipgrepMatch[] = [];
		let totalMatches = 0;

		const rg = spawn(rgPath, args, {
			cwd: target.cwd,
			env: { ...process.env },
		});

		let stdout = '';
		let stderr = '';

		rg.stdout.on('data', (data) => {
			stdout += data.toString();
		});

		rg.stderr.on('data', (data) => {
			stderr += data.toString();
		});

		rg.on('close', (code) => {
			// ripgrep returns 0 for matches found, 1 for no matches, 2 for errors
			if (code === 2) {
				reject(new Error(`ripgrep error: ${stderr}`));
				return;
			}

			// Parse JSON lines output
			const lines = stdout.split('\n').filter((line) => line.trim());

			for (const line of lines) {
				try {
					const entry = JSON.parse(line);
					if (entry.type !== 'match') {
						continue;
					}

					const data = entry.data;

					// Security check: ensure the file belongs to the target
					const displayPath = target.toDisplayPath(data.path.text);
					if (!displayPath) {
						continue;
					}

					for (const _submatch of data.submatches) {
						totalMatches++;

						if (matches.length < max_results) {
							matches.push({
								path: displayPath,
								line_number: data.line_number,
								line_content: data.lines.text.replace(/\n$/, ''),
							});
						}
					}
				} catch {
					// Skip malformed lines
				}
			}

			// If context was requested, do a second pass to collect it
			if (context_lines && context_lines > 0 && matches.length > 0) {
				addContextToMatches(matches, context_lines, target);
			}

			resolve({ matches, totalMatches });
		});

		rg.on('error', (err) => {
			reject(new Error(`Failed to run ripgrep: ${err.message}`));
		});
	});
}

/**
 * Add context lines to matches by reading the files.
 */
function addContextToMatches(matches: RipgrepMatch[], contextLines: number, target: SearchTarget): void {
	// Group matches by file for efficiency
	const matchesByFile = new Map<string, RipgrepMatch[]>();
	for (const match of matches) {
		const existing = matchesByFile.get(match.path) || [];
		existing.push(match);
		matchesByFile.set(match.path, existing);
	}

	for (const [displayPath, fileMatches] of matchesByFile) {
		try {
			const content = fs.readFileSync(target.toAbsolutePath(displayPath), 'utf-8');
			const lines = content.split('\n');

			for (const match of fileMatches) {
				const lineIndex = match.line_number - 1; // Convert to 0-indexed

				// Get context before
				const beforeStart = Math.max(0, lineIndex - contextLines);
				match.context_before = lines.slice(beforeStart, lineIndex);

				// Get context after
				const afterEnd = Math.min(lines.length, lineIndex + 1 + contextLines);
				match.context_after = lines.slice(lineIndex + 1, afterEnd);
			}
		} catch {
			// Skip files that can't be read
		}
	}
}

